    {
      "id": 1,
      "type": "stat",
      "title": "E2E Success Rate (15m/1h/24h)",
      "datasource": {
        "type": "prometheus",
        "uid": "prometheus"
      },
      "gridPos": {
        "h": 6,
        "w": 12,
        "x": 0,
        "y": 0
      },
      "fieldConfig": {
        "defaults": {
          "unit": "percentunit",
          "decimals": 2,
          "min": 0,
          "max": 1
        },
        "overrides": [
          {
            "matcher": {
              "id": "byName",
              "options": "Starts 15m"
            },
            "properties": [
              {
                "id": "unit",
                "value": "short"
              },
              {
                "id": "decimals",
                "value": 0
              },
              {
                "id": "min",
                "value": null
              },
              {
                "id": "max",
                "value": null
              }
            ]
          }
        ]
      },
      "options": {
        "reduceOptions": {
          "calcs": [
            "lastNotNull"
          ],
          "fields": "",
          "values": false
        },
        "orientation": "horizontal",
        "textMode": "value",
        "colorMode": "value",
        "graphMode": "none",
        "justifyMode": "auto"
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum(rate(app-s_e2e_outcome_total{outcome=\"success\",namespace=~\"$backend_namespace\"}[15m])) / sum(rate(app-s_e2e_start_total{namespace=~\"$backend_namespace\"}[15m]))",
          "legendFormat": "SR 15m",
          "instant": true
        },
        {
          "refId": "B",
          "expr": "sum(rate(app-s_e2e_outcome_total{outcome=\"success\",namespace=~\"$backend_namespace\"}[1h])) / sum(rate(app-s_e2e_start_total{namespace=~\"$backend_namespace\"}[1h]))",
          "legendFormat": "SR 1h",
          "instant": true
        },
        {
          "refId": "C",
          "expr": "sum(rate(app-s_e2e_outcome_total{outcome=\"success\",namespace=~\"$backend_namespace\"}[24h])) / sum(rate(app-s_e2e_start_total{namespace=~\"$backend_namespace\"}[24h]))",
          "legendFormat": "SR 24h",
          "instant": true
        },
        {
          "refId": "D",
          "expr": "sum(increase(app-s_e2e_start_total{namespace=~\"$backend_namespace\"}[15m]))",
          "legendFormat": "Starts 15m",
          "instant": true
        }
      ]
    },
    {
      "id": 2,
      "type": "timeseries",
      "title": "E2E Latency p95/p99 (5 segments)",
      "datasource": {
        "type": "prometheus",
        "uid": "prometheus"
      },
