        "name": "backend_namespace",
        "label": "Backend Namespace",
        "type": "custom",
        "query": "prod-app-s,dev-app-s",
        "multi": true,
        "includeAll": true,
        "allValue": ".*",
        "current": {
          "text": "prod-app-s",
          "value": "prod-app-s",
          "selected": true
        },
        "options": [
          {
            "text": "All",
            "value": ".*",
            "selected": false
          },
          {
            "text": "prod-app-s",
